import math


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif ch in "+-*/%^!()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f"Unexpected character: {ch!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0
    num_tokens = len(tokens)

    def peek():
        return tokens[pos] if pos < num_tokens else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr() -> int:
        val = parse_mul_div()
        while peek() in ("+", "-"):
            op = advance()
            rhs = parse_mul_div()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def parse_mul_div() -> int:
        val = parse_unary()
        while True:
            tok = peek()
            if tok == "*":
                advance()
                val *= parse_unary()
            elif tok == "/":
                advance()
                rhs = parse_unary()
                if rhs == 0:
                    raise ValueError("Division by zero")
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) ^ (rhs < 0) else q
            elif tok == "%":
                advance()
                rhs = parse_unary()
                if rhs == 0:
                    raise ValueError("Remainder by zero")
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
            elif tok == "(":
                val *= parse_unary()
            else:
                break
        return val

    def parse_unary() -> int:
        neg = False
        while peek() == "-":
            advance()
            neg = not neg
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        base = parse_postfix()
        if peek() == "^":
            advance()
            exp = parse_unary()
            if exp < 0:
                raise ValueError("Negative exponent")
            return pow(base, exp)
        return base

    def parse_postfix() -> int:
        val = parse_primary()
        while peek() == "!":
            advance()
            if val < 0:
                raise ValueError("Factorial of a negative number")
            val = math.factorial(val)
        return val

    def parse_primary() -> int:
        tok = peek()
        if isinstance(tok, int):
            advance()
            return tok
        if tok == "(":
            advance()
            val = parse_expr()
            if peek() != ")":
                raise ValueError("Mismatched parentheses")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expr()
    if pos != num_tokens:
        raise ValueError(f"Unexpected token: {tokens[pos]!r}")
    return result
